def word_frequency(
    text,
):
    """
    Calculates the frequency of each word in a given text.

    Args:
        text (str): The input string.

    Returns:
        dict: A dictionary where keys are words (lowercase) and values are their frequencies.
    """
    words = text.lower().split()
    frequency = {}
    for word in words:
        cleaned_word = ''.join(
            char
            for char in word
            if char.isalnum()
        )
        if cleaned_word:
            frequency[cleaned_word] = frequency.get(
                cleaned_word,
                0,
            ) + 1
    return frequency

def process_multiple_texts(
    texts,
    output_format='dict',
    sort_by_frequency=False,
    top_n=None,
):
    all_frequencies = {}
    for t in texts:
        current_freq = word_frequency(
            t,
        )
        for word, count in current_freq.items():
            all_frequencies[word] = all_frequencies.get(
                word,
                0,
            ) + count

    if sort_by_frequency:
        sorted_items = sorted(
            all_frequencies.items(),
            key=lambda item: item[1],
            reverse=True,
        )
        if top_n is not None:
            return sorted_items[:top_n]
        return sorted_items
    return all_frequencies

if __name__ == '__main__':
    sample_text = 'Hello world, hello Python! Python is great.'
    result = word_frequency(
        sample_text,
    )
    print(
        result,
    )

    texts_list = [
        'Python is fun.',
        'Fun with Python.',
        'Hello Python!',
    ]
    combined_freq = process_multiple_texts(
        texts_list,
        sort_by_frequency=True,
        top_n=2,
    )
    print(
        combined_freq,
    )

