import math

def geometric_mean(
    numbers,
):
    """
    Calculates the geometric mean of a list of positive numbers.
    """
    if not numbers:
        return 0.0

    product = math.prod(
        numbers,
    )
    n = len(
        numbers,
    )
    return product**(
        1 / n
    )

def test_geometric_mean():
    assert geometric_mean(
        [2, 8],
    ) == 4.0
    assert geometric_mean(
        [1, 1, 1],
    ) == 1.0
    assert geometric_mean(
        [3, 9, 27],
    ) == 9.0
    assert geometric_mean(
        [10],
