    text,
):
    sentences = []
    current_sentence_start = 0
    for i, char in enumerate(
        text,
    ):
        if char in (
            '.',
            '!',
            '?',
        ):
            sentences.append(
                text[current_sentence_start : i + 1],
            )
            current_sentence_start = i + 1
    if current_sentence_start < len(
        text,
    ):
        sentences.append(
            text[current_sentence_start:],
        )

    capitalized = []
    for sentence in sentences:
        stripped_sentence = sentence.lstrip()
        if stripped_sentence:
            capitalized.append(
                sentence[: len(sentence) - len(stripped_sentence)]
                + stripped_sentence[0].upper()
                + stripped_sentence[1:],
            )
        else:
            capitalized.append(
                sentence,
            )
    return ''.join(
        capitalized,
    )

