def run_length_encode(
    input_string,
):
    if not input_string:
        return ""

    encoded_parts = []
    current_char = input_string[0]
    current_count = 1

    for char_index in range(
        1,
        len(input_string),
    ):
        if input_string[char_index] == current_char:
            current_count += 1
        else:
            encoded_parts.append(
                f"{current_char}{current_count}"
            )
            current_char = input_string[char_index]
            current_count = 1

    encoded_parts.append(
        f"{current_char}{current_count}"
    )

    return "".join(
        encoded_parts
    )

